        \draw[green!80!black,thick] (.5,-0.7) .. controls (.3,-1) .. (0,-1);
        \draw[green!80!black,thick] (6,-1.15) .. controls (5,-1.6) .. (0,-1.6);


  \pgfmathsetmacro{\mid}{(0+1)/2} 
  \pgfmathsetmacro{\rad}{(1-0)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=1*\rad];
  \node[bigdot] at (\mid, -0.21-1*\rad) {}; 


  \pgfmathsetmacro{\mid}{(3+4)/2} 
  \pgfmathsetmacro{\rad}{(4-3)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=1*\rad];


  \pgfmathsetmacro{\mid}{(2+5)/2} 
  \pgfmathsetmacro{\rad}{(5-2)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=.75*\rad];


  \draw[strand] (6,-0.21) -- (6,-2);
  \node[bigdot] at (6, {(-0.21-2)/2}) {}; 


  \foreach \i in {0,...,\numexpr7-1\relax} {
    \draw[strand] (\i,0) -- (\i,-0.21);
  }


        \draw[dotted,thick] (0,0) -- (6,0);
        \draw[dotted,thick] (0,-2) -- (6,-2);
        \draw[dotted,thick] (0,0) -- (0,-2);
    \end{tikzpicture}$$
    And the following diagram is not a cup diagram because the decorated cup is on the right of a vertical line.
    $$\begin{tikzpicture}[scale=0.8]
        \draw[red,thick] (5.5,-0.7) .. controls (4.5,-1.3) .. (4,-1.3);


  \pgfmathsetmacro{\mid}{(0+1)/2} 
  \pgfmathsetmacro{\rad}{(1-0)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=1*\rad];


  \pgfmathsetmacro{\mid}{(2+3)/2} 
  \pgfmathsetmacro{\rad}{(3-2)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=1*\rad];


  \pgfmathsetmacro{\mid}{(5+6)/2} 
  \pgfmathsetmacro{\rad}{(6-5)/2} 
  \draw[strand] (\mid-\rad,-0.21)
    arc[start angle=-180,end angle=0,
        x radius=\rad,
        y radius=1*\rad];
  \node[bigdot] at (\mid, -0.21-1*\rad) {}; 


  \draw[strand] (4,-0.21) -- (4,-2);


  \foreach \i in {0,...,\numexpr7-1\relax} {
    \draw[strand] (\i,0) -- (\i,-0.21);
  }


        \draw[dotted,thick] (0,0) -- (6,0);
        \draw[dotted,thick] (0,-2) -- (6,-2);
        \draw[dotted,thick] (0,0) -- (0,-2);
        \draw[dotted,thick] (6,0) -- (6,-2);
    \end{tikzpicture}$$

\label{def:4.6}
    Let $n \geq 1$ be an integer and $p \in \{0,1\}$. We fix a horizontal line in the plane and $n$ distinct points on it. An arc diagram associated to the block $\Delta_n^p$, is the glueing of a cup and a cap diagram of size $n$ along a weight belonging to $\Delta_n^p$, satisfying the following conditions.
    \begin{enumerate}
        \item[\textit{(i)}] Any undecorated cup or cap is glued to exactly one ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,-.1) -- (0,.1);
\end{tikzpicture}\mkern.5mu}$ and one ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,.1) -- (0,-.1);
\end{tikzpicture}\mkern.5mu}$.
        \item[\textit{(ii)}] Any decorated cup or cap is glued to either two ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,-.1) -- (0,.1);
\end{tikzpicture}\mkern.5mu}$'s or two ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,.1) -- (0,-.1);
\end{tikzpicture}\mkern.5mu}$'s.
        \item[\textit{(iii)}] Any undecorated half line is glued to one ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,.1) -- (0,-.1);
\end{tikzpicture}\mkern.5mu}$.
        \item[\textit{(iv)}] Any decorated half line is glued to one ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,-.1) -- (0,.1);
\end{tikzpicture}\mkern.5mu}$.
    \end{enumerate}
