        \item Draw undecorated half-lines extending downwards starting at every remaining ${\mkern.5mu\begin{tikzpicture}[x=.27em,y=.45em,decoration={markings,mark=at position 0.99 with {\arrow[black]{Stealth[length=4.8pt]}}}]
\draw[color=white,postaction={decorate}] (0,.1) -- (0,-.1);
