    $$\Phi_{\alpha\beta\delta} : {}_\alpha(\mathbb{D} _n^p)_\beta \otimes {}_\beta(\mathbb{D} _n^p)_\delta \xrightarrow{\varphi_{\underline{\alpha}\overline{\beta}} \otimes \varphi_{\underline{\beta}\overline{\delta}}} \mathcal{M}(\underline{\alpha}\overline{\beta}) \otimes \mathcal{M}(\underline{\beta}\overline{\delta}) \xrightarrow{\chi} \mathcal{M}(\underline{\alpha}\overline{\delta}) \xrightarrow{(\varphi_{\underline{\alpha}\overline{\delta}})^{-1}} {}_\alpha(\mathbb{D} _n^p)_\delta $$
