    \textbf{Monomial relations :} The length $2$ paths from the top to the bottom, and from the bottom to the top of figures $\textit{(a)}$, $\textit{(b)}$, $\textit{(c)}$ and $\textit{(d)}$ from Lemma~\ref{lem:5.11}.

    \textbf{Square relations :} The difference of any parallel legth $2$ paths from any square from Lemma~\ref{lem:5.10}.

    \textbf{Relations at vertices :} The following linear combinations of paths starting and ending at $\lambda$
    $$y_\kappa^\lambda x_\kappa^\lambda - \sum_{i=1}^{\text{def}(\lambda)} d_\kappa^{\mu_i}(\lambda) x_\lambda^{\mu_i} y_\lambda^{\mu_i}$$
    Where the coefficients $d_\kappa^{\mu_i}(\lambda)$ are given by 
    $$
    d_\kappa^{\mu_i}(\lambda) =
    \begin{cases}
        1  &\text{ if } C_i \text{ does not appear in } e_\kappa \text{ and does not enclose another }\\[-1ex]
        &\text{ circle } C_j \text{ that does not appear either in } e_\kappa,\\[1ex]

        -2 &\text{ if } C_i \text{ does not appear in } e_\kappa \text{ and encloses another }\\[-1ex]
        &\text{ circle } C_j \text{ that does not appear either in } e_\kappa,\\[1ex]

        0 &\text{ if } C_i \text{ appears in } e_\kappa \text{ and does not enclose } D, \\[1ex]

        (-1)^{j-1}2 &\text{ if } C_i \text{ appears in } e_\kappa \text{ and is the } j \text{th circle enclosing } D.
    \end{cases}
    $$

