    because $c_\kappa^{\mu_i}(\lambda) = 0$ for all $3 \leq i \leq \text{def}(\lambda)$, if they exist (and $d_\kappa^{\mu_2}(\lambda) = -2$). The tenth subcase is analogous. These are the only subcases where the coefficient $d_\kappa^{\mu_i}(\lambda) = -2$ occurs.

\label{lem:5.17}
    Let $\lambda, \mu \in \Delta_n^0$, then we have
    $$
    \text{dim}_\Bbbk \left( e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu \right) \leq
    \begin{cases}
        1  &\text{ if } \lambda \neq \mu,\\
        \text{def}(\lambda) &\text{ if } \lambda = \mu.
    \end{cases}
    $$

\label{lem:5.18}
    Let $\lambda \neq \mu \in \Delta_n^0$, then
    $$\text{dim}_\Bbbk \left( e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu \right) = \text{dim}_\Bbbk \left( e_\lambda ( \mathbb{D} _n )_2 e_\mu \right).$$

Since $\overline{\omega}$ is surjective, and thanks to Lemma~\ref{lem:5.17}, we have that
    $$1 \geq \text{dim}_\Bbbk \left( e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu \right) \geq \text{dim}_\Bbbk \left( e_\lambda ( \mathbb{D} _n )_2 e_\mu \right)$$
    Observe that if 
    $$\text{dim}_\Bbbk \left( e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu \right) = 0$$
    we're done. So suppose that
    $$\text{dim}_\Bbbk \left( e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu \right) = 1$$
    and then there exists a length $2$ path $p$ from $e_\lambda$ to $e_\mu$ such that $[p] \neq 0$ in $e_\lambda ( \Bbbk Q_n/I_n )_2 e_\mu$. \\
